/* Intro: ENTER -> jalan malam dengan logo naga -> WELCOME -> website (sekali per sesi).
   Tambah ?intro di URL untuk memutar ulang. Ganti teks di CFG di bawah. */
(function(){
const root=document.getElementById('flaIntro');
if(!root){document.documentElement.classList.remove('fla-lock');return}
let seen=false;try{seen=sessionStorage.getItem('flaIntroSeen')==='1'}catch(e){}
if(seen&&!/[?&]intro(=|&|$)/.test(location.search)){document.documentElement.classList.remove('fla-lock');root.remove();return}

const CFG={enter:'ENTER',title:'WELCOME',sub:'MY PORTOFOLIO',btn:'MASUK',href:''}; // ganti teks / isi href dengan link website
const LOGO="data:image/png;base64,";
const $=i=>document.getElementById(i);
document.querySelectorAll('#flaIntro [data-l]').forEach(e=>e.src=LOGO);
$('dien').textContent=CFG.enter;$('disb').textContent=CFG.sub;$('digo').textContent=CFG.btn;
$('ditt').innerHTML=[...CFG.title].map((c,i)=>`<span style="--i:${i}">${c}</span>`).join('');
$('digo').onclick=e=>{e.preventDefault();finish()};
$('dirp').onclick=()=>{location.href=location.pathname+'?intro'};
/* aspal */
(()=>{const c=document.createElement('canvas');c.width=c.height=256;const g=c.getContext('2d'),d=g.createImageData(256,256);for(let i=0;i<d.data.length;i+=4){let v=26+Math.random()*28;if(Math.random()<.04)v+=40+Math.random()*50;d.data[i]=d.data[i+1]=d.data[i+2]=v;d.data[i+3]=255}g.putImageData(d,0,0);$('diA').style.backgroundImage='url('+c.toDataURL()+')'})();
/* suara */
let AC;const au=()=>{try{AC=AC||new(window.AudioContext||window.webkitAudioContext)();AC.resume()}catch(e){}};
function tone(f0,f1,d,g,t=0){if(!AC)return;const o=AC.createOscillator(),n=AC.createGain(),T=AC.currentTime+t;o.frequency.setValueAtTime(f0,T);o.frequency.exponentialRampToValueAtTime(f1,T+d);n.gain.setValueAtTime(g,T);n.gain.exponentialRampToValueAtTime(.001,T+d);o.connect(n).connect(AC.destination);o.start(T);o.stop(T+d)}
function noise(d,f0,f1,g,t=0){if(!AC)return;const b=AC.createBuffer(1,AC.sampleRate*d|0,AC.sampleRate),a=b.getChannelData(0);for(let i=0;i<a.length;i++)a[i]=Math.random()*2-1;const s=AC.createBufferSource(),F=AC.createBiquadFilter(),n=AC.createGain(),T=AC.currentTime+t;s.buffer=b;F.type='bandpass';F.Q.value=1.2;F.frequency.setValueAtTime(f0,T);F.frequency.exponentialRampToValueAtTime(f1,T+d);n.gain.setValueAtTime(.0001,T);n.gain.linearRampToValueAtTime(g,T+d*.8);n.gain.linearRampToValueAtTime(.0001,T+d);s.connect(F).connect(n).connect(AC.destination);s.start(T)}
/* jalan malam */
const cv=$('dicv'),x=cv.getContext('2d');let W,H,f0,HY,SK,Q=1;const BL=document.createElement('canvas'),bx=BL.getContext('2d');
const R=6,hc=2.6,LP=156,LZ0=112,LW=10,F=[42,18,86];let LG,LL=5;
const mx=(c,t)=>`rgb(${c[0]+(F[0]-c[0])*t|0},${c[1]+(F[1]-c[1])*t|0},${c[2]+(F[2]-c[2])*t|0})`;
const hs=(a,b,c)=>{const n=Math.sin(a*127.1+b*311.7+c*74.7)*43758.5453;return n-Math.floor(n)};
function rs(){let d=Math.min(devicePixelRatio||1,2)*Q;const px=innerWidth*innerHeight*d*d;if(px>4.2e6)d*=Math.sqrt(4.2e6/px);W=cv.width=innerWidth*d|0;H=cv.height=innerHeight*d|0;x.imageSmoothingQuality='high';f0=Math.max(W*.62,H*.5);HY=H*.4;BL.width=W>>3;BL.height=H>>3;SK=x.createLinearGradient(0,0,0,HY);SK.addColorStop(0,'#02030a');SK.addColorStop(.6,'#0b0822');SK.addColorStop(1,'#2a1058')}
addEventListener('resize',rs);rs();
const L=new Image();L.onload=()=>{const m=100,iw=900,ih=iw*L.naturalHeight/L.naturalWidth;LG=document.createElement('canvas');LG.width=iw+2*m;LG.height=Math.round(ih+2*m);const g=LG.getContext('2d');g.shadowColor='#35d8ff';g.imageSmoothingQuality='high';g.shadowBlur=50;g.drawImage(L,m,m,iw,ih);g.drawImage(L,m,m,iw,ih);g.shadowBlur=0;g.drawImage(L,m,m,iw,ih);LL=LW*LG.height/LG.width};L.src=LOGO;
const PAL=[[16,18,34],[22,16,40],[12,24,38],[20,20,30],[28,16,34]],WC=['#ffd27a','#8fe9ff','#ff6ad5','#fff'],SG=[[0,230,255],[255,60,200],[255,190,60]],B=[];
for(const sd of[-1,1])for(let i=0;i<30;i++){const id=B.length+1;B.push({id,sd,z:i*LP/30+hs(id,1,1)*2,dl:3.5+hs(id,2,1)*3.5,bh:9+hs(id,3,1)*34,o:R+1.6+hs(id,4,1)*1.8,c:PAL[id%5],sg:hs(id,5,1)>.55?SG[id%3]:0})}
function draw(t){
 const D=6,u=Math.min(t/D,1),sm=(a,b)=>{const q=Math.max(0,Math.min(1,(t-a)/(b-a)));return q*q*(3-2*q)},cam=106*(.5-.5*Math.cos(Math.PI*u)),sp=106*1.57*Math.sin(Math.PI*u)/D,f=f0*(1+.14*(1-sm(0,1.8)));
 const X0=W/2+Math.sin(t*1.3)*W*.006,Y0=HY-sm(D-2,D)*H*.08+Math.sin(t*8)*H*.0015*(sp/18);
 x.globalCompositeOperation='source-over';x.globalAlpha=1;x.fillStyle=SK;x.fillRect(0,0,W,H);
 const gg=x.createRadialGradient(X0,Y0,0,X0,Y0,W*.55);gg.addColorStop(0,'rgba(140,80,255,.45)');gg.addColorStop(1,'rgba(140,80,255,0)');
 x.globalCompositeOperation='lighter';x.fillStyle=gg;x.fillRect(0,0,W,Y0+H*.05);x.globalCompositeOperation='source-over';
 for(let y=Math.ceil(Y0)+1;y<H;y++){
  const z=hc*f/(y-Y0),s=f/z,zw=z+cam,fg=Math.min(1,z/120);
  x.fillStyle=mx([8,9,14],fg);x.fillRect(0,y,W,1);
  x.fillStyle=mx([26,27,36],fg);x.fillRect(X0-(R+1.2)*s,y,(2*R+2.4)*s,1);
  x.fillStyle=mx([14,15,21],fg);x.fillRect(X0-R*s,y,2*R*s,1);
  const lw=Math.max(1,.14*s);x.fillStyle=mx([190,195,210],fg);
  x.fillRect(X0-(R-.35)*s,y,lw,1);x.fillRect(X0+(R-.35)*s-lw,y,lw,1);
  for(const lx of[-3,0,3])if(((zw+(lx?4:0))%8+8)%8<4)x.fillRect(X0+lx*s-lw/2,y,lw,1);
  const dz=zw-LZ0;
  if(LG&&dz>=0&&dz<LL){const sy=Math.min(LG.height-1,Math.max(0,(1-dz/LL)*LG.height|0)),w=LW*s;x.drawImage(LG,0,sy,LG.width,1,X0-w/2,y,w,1)}
 }
 const vis=B.map(b=>[((b.z-cam)%LP+LP)%LP+.6,b]).sort((a,b)=>b[0]-a[0]);
 for(const[z1,b]of vis){
  const z2=z1+b.dl,fg=Math.min(1,Math.max(0,(z1-35)/105)),X=b.sd*b.o,id=b.id;
  const P=(zz,g,xx)=>[X0+(xx??X)*f/zz,Y0+(hc-g)*f/zz];
  let p=[P(z1,0),P(z2,0),P(z2,b.bh),P(z1,b.bh)];
  x.fillStyle=mx(b.c,fg);x.beginPath();p.forEach((q,i)=>i?x.lineTo(q[0],q[1]):x.moveTo(q[0],q[1]));x.fill();
  const X2=X+b.sd*6;p=[P(z1,0),P(z1,b.bh),P(z1,b.bh,X2),P(z1,0,X2)];
  x.fillStyle=mx([30,26,58],fg);x.beginPath();p.forEach((q,i)=>i?x.lineTo(q[0],q[1]):x.moveTo(q[0],q[1]));x.fill();
  if(z1<100){const nr=Math.min(14,b.bh/2.4|0);x.globalAlpha=(1-fg)*.9;
   for(let r=0;r<nr;r++)for(let k=0;k<3;k++){if(hs(id,k,r)<.5)continue;
    const za=z1+(z2-z1)*(k+.2)/3,zb=z1+(z2-z1)*(k+.75)/3,zm=(za+zb)/2,g0=r*2.4+.7,xa=X0+X*f/za,xb=X0+X*f/zb;
    x.fillStyle=WC[hs(id,k+9,r)*4|0];x.fillRect(Math.min(xa,xb),Y0+(hc-g0-1.1)*f/zm,Math.abs(xb-xa)+.5,1.1*f/zm)}
   x.globalAlpha=1}
  if(b.sg&&b.bh>18){x.globalCompositeOperation='lighter';
   for(const[g0,g1,a]of[[14,17,.9],[13,18,.25]]){x.fillStyle=`rgba(${b.sg},${a*(1-fg)})`;x.beginPath();[P(z1,g0),P(z2,g0),P(z2,g1),P(z1,g1)].forEach((q,i)=>i?x.lineTo(q[0],q[1]):x.moveTo(q[0],q[1]));x.fill()}
   x.globalCompositeOperation='source-over'}
 }
 x.globalCompositeOperation='lighter';
 for(let k=0;k<22;k++){const z=((k*10-cam)%220+220)%220+1;if(z<4)continue;const s=f/z,a=1-Math.min(1,z/160);
  for(const sd of[-1,1]){const px=X0+sd*(R+.7)*s,py=Y0+(hc-5.5)*s,r=Math.max(1.5,.45*s);
   x.fillStyle=`rgba(255,190,110,${.25*a})`;x.beginPath();x.arc(px,py,r*2.2,0,7);x.fill();
   x.fillStyle=`rgba(255,235,200,${a})`;x.beginPath();x.arc(px,py,r,0,7);x.fill()}}
 bx.drawImage(cv,0,0,BL.width,BL.height);x.globalCompositeOperation='lighter';x.globalAlpha=.4;x.drawImage(BL,0,0,W,H);x.globalAlpha=1;x.globalCompositeOperation='source-over';
}
/* alur */
let st=0,t0=0,run=0;const TM=[],to=(fn,ms)=>TM.push(setTimeout(fn,ms));
let lt=0,fc=0,ac=0;function loop(){if(!run)return;const n=performance.now();if(lt){ac+=n-lt;fc++;if(fc==24){if(ac/fc>26&&Q>.55){Q*=.8;rs()}fc=ac=0}}lt=n;draw((n-t0)/1000);requestAnimationFrame(loop)}
function go(){if(st)return;st=1;au();tone(150,40,.4,.7);noise(1.2,200,5000,.45,.15);
 const br=$('dibd').getBoundingClientRect(),rw=$('dirow').getBoundingClientRect();
 $('dirow').style.transformOrigin=(br.left+br.width/2-rw.left)+'px '+(br.top+br.height/2-rw.top)+'px';
 $('dibw').classList.add('press');to(()=>$('diA').classList.add('zoom'),160);
 to(()=>{$('diB').classList.add('on');t0=performance.now();run=1;noise(6,180,2600,.32);loop()},800);
 to(()=>$('diA').style.display='none',1900);
 to(()=>{$('difl').style.transition='opacity .8s cubic-bezier(.4,0,.2,1)';$('difl').style.opacity=1;tone(70,28,1.6,.8,.5);noise(1.1,3000,200,.4,.4);
  to(()=>{toC();$('difl').style.transition='opacity 1.3s ease';$('difl').style.opacity=0},900)},800+5600)}
function toC(){st=2;run=0;$('diA').style.display=$('diB').style.display=$('disk').style.display='none';$('diC').classList.add('on')}
function finish(){try{sessionStorage.setItem('flaIntroSeen','1')}catch(e){}run=0;try{AC&&AC.close()}catch(e){}document.documentElement.classList.remove('fla-lock');root.classList.add('out');setTimeout(()=>root.remove(),1000)}
$('diA').onclick=go;addEventListener('keydown',e=>{if(!root)return;if(st===0&&(e.key==='Enter'||e.key===' '))go();if(e.key==='Escape')$('disk').onclick()});
$('disk').onclick=()=>{if(st>1)return;TM.forEach(clearTimeout);try{AC&&AC.close()}catch(e){}toC()};

})();
